      showTool:false,
      sitio:'abajo-derecha',
      escala: 0.8,
      html:
      '<div class="mc-osd-panel">' +
        '<div class="mc-osd-title">VoxelForge v1.0</div>' +
        '<button class="mc-osd-btn">EMPTY -> FPS</button>' +
        '<button class="mc-osd-btn">CONSTRUIR</button>' +
        '<button class="mc-osd-btn">AJUSTES</button>' +
        '<button class="mc-osd-btn">RESET</button>' +
        '<button class="mc-osd-btn">JUGAR</button>' +
      '</div>'});

const htmlVolar = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">Mi menú '+game.volar.valueOf() +'</div>'
  + '<button class="mc-osd-btn" data-osd="VOLAR">VOLAR: ' + (game.volar.valueOf() ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn">REGRESAR</button>'
  + '</div>';

game.osd.define('mi_menu_volar', {
      mapa:'voxelforge', pos:encuadre.pos, yaw:encuadre.yaw, pitch:encuadre.pitch,
      sitio:'abajo-derecha',
      html:htmlVolar()
});

game.osd.alPulsar('INTRO', () => { game.snippet("arranque-intro"); });
game.osd.alPulsar('EMPTY -> FPS', () => { location.href="/map/fps?intro=1" });
game.osd.alPulsar('AJUSTES', () => { game.osd.conmutar("mi_menu_volar"); });
game.osd.alPulsar('RESET', () => { game.snippet("reset-map"); });
game.osd.alPulsar('VOLAR', () => {
  game.volar();                 // conmuta
  game.osd.html(htmlVolar());   // ← re-evalúa la plantilla: el texto sigue al estado
});
game.osd.alPulsar('REGRESAR', () => { game.osd.conmutar("mi_menu"); });
game.osd.alPulsar('JUGAR', () => { 
  if(mc._intro!=null) mc._intro.parar()
  game.fantasma(false);
  game.snippet("miosd",{noshow:true,ambiente:"NIEBLA"})
  game.osd.cerrar();  
  game.showTool(true) 
  mcLockPointer(); 
});

game.osd.abrir("mi_menu")

game.onKey('o', () => {
  game.osd.abrir('mi_menu')
})
